{
  "primary_actions": [
    {
      "time_range": "0.0-2.0",
      "description": "Urco initiates violent full-body shake: head snaps left-right, torso twists, hindquarters follow in wave motion. Chains slack then snap taut. Water droplets eject radially from fur at high velocity."
    },
    {
      "time_range": "2.0-3.5",
      "description": "Octopus enters frame from upper left (dislodged by shake), travels in ballistic arc. Impacts Urco's snout/eye region with visible deformation. Suction cups engage sequentially with audible timing."
    },
    {
      "time_range": "3.5-7.0",
      "description": "Urco blinded: spins clockwise on forepaws, hind legs scrabbling on wet granite. Chains whip horizontally at head height, carving arcs through spray. Paws impact rocks with audible thuds. Body weight shifts violently side-to-side."
    },
    {
      "time_range": "7.0-10.5",
      "description": "Percebeiro reacts: initial backward stumble, then lateral sprint along rock ridge. Leaps over low-swinging chain link (0.5m clearance). Slips on algae-slick rock, recovers with hand plant. Dodges second chain whip by dropping prone."
    },
    {
      "time_range": "10.5-12.0",
      "description": "Urco crashes sideways into boulder, chain anchor point groans. Percebeiro scrambles up incline away from surf line."
    }
  ],
  "subject_motion": {
    "urco": "0-2s: Rotational shake axis along spine, frequency ~4Hz, amplitude decaying. 2-3.5s: Head snap-back on impact, eyes clamp shut. 3.5-7s: Continuous spin ~90deg/sec, center of mass orbits 1.5m radius. Chains describe figure-8 patterns. 7-12s: Momentum carries into boulder collision, rebound, partial collapse.",
    "percebeiro": "0-3.5s: Static tension, weight on balls of feet. 3.5-7s: Micro-adjustments tracking Urco. 7-10.5s: Explosive lateral displacement 3m, vertical leap 0.8m, prone drop 1.2m, scramble 2m uphill. Limbs splay for friction on wet rock.",
    "octopus": "2.0-3.5s: Rigid-body tumble 2 rev/sec. Impact: mantle compresses 40%, arms splay radially. 3.5-7s: Arms adhere sequentially (0.1s intervals), mantle pulses. Chromatophores flash maroon-to-pale."
  },
  "environmental_motion": {
    "waves": "Breaking on offshore reef: 3 major impacts at 1.2s, 4.8s, 9.1s. Whitewater plumes rise 8m, fall as sheet spray.",
    "spray": "Wind-driven horizontal sheets at 15m/s. Droplet size 0.5-3mm. Accumulates on lens as partial occlusion 4-6s.",
    "rocks": "Static. Surface water films flow downhill 0.2m/s. Algae patches undulate in surge.",
    "sky": "Cloud bases lower 50m over 12s. Stratocumulus bands rotate cyclonically slow."
  },
  "particle_motion": {
    "shake_droplets": "0-2.5s: 5000+ droplets 1-4mm, initial velocity 12m/s radial. Ballistic arcs 2-3m. Catch backlight.",
    "impact_spray": "2.5-3.5s: Octopus impact ejecta - mucus-water mix, high viscosity strands 10cm long.",
    "chain_spray": "3.5-10s: Chain links fling bound water in tight spirals. Droplets 2mm, velocity 8m/s tangential.",
    "surf_aerosol": "Continuous: Sub-100um salt nuclei in suspension. Visibility 30m at camera height."
  },
  "lighting_motion": {
    "ambient": "Global illuminance drops 15% over 12s (cloud thickening). Color temp shifts 5500K->5000K.",
    "specular": "Wet fur highlights track body rotation. Chain links flash point-reflections at 3.5s, 5.2s, 7.8s. Octopus mantle catches highlight at 3.0s.",
    "shadow": "Urco's shadow sweeps rocks during spin. Penumbra softens as cloud thickens."
  },
  "camera_motion": {
    "0-3.5s": "Static low tripod (0.4m height), 24mm equiv. Slight micro-jitter (0.5px) from wind.",
    "3.5-7s": "Pan right 25deg at 7deg/sec tracking Percebeiro. Tilt up 5deg to include chain arcs.",
    "7-10.5s": "Handheld follow: dolly left 1.5m at 0.4m/s, yaw left 15deg. Roll ±2deg from uneven footing.",
    "10.5-12s": "Pedestal up 0.3m, zoom 24->35mm (digital crop). Frame Urco collapse and Percebeiro escape."
  },
  "physics_reactions": {
    "chains": "Mass 15kg/m. Slack-to-taut transitions at 3.2s, 5.0s, 6.8s. Link collision energy dissipates as heat/sound. Anchor ring deforms rock surface <1mm.",
    "fur": "Wet clump separation at 4Hz shake. Surface tension bridges break at 0.3s intervals. Re-clumping during spin via centrifugal mat.",
    "rock_contact": "Paw pressure 400kPa on impact. Granite fracture risk at existing fissures. Algae shear at 0.1m/s slip.",
    "octopus_adhesion": "Suction cup pressure differential -60kPa. Detachment force >200N per arm. Viscoelastic mucus strand failure at 15cm extension."
  },
  "timing_beats": [
    "0.0: Shake onset",
    "1.2: Wave boom 1",
    "2.1: Octopus launch visible",
    "2.8: SPLAT impact",
    "3.0: First suction pop",
    "3.5: Spin initiation",
    "4.8: Wave boom 2",
    "5.5: Chain shriek peak",
    "7.0: Percebeiro flight",
    "7.3: Chain leap clearance",
    "8.1: Prone dodge",
    "9.1: Wave boom 3",
    "10.2: Boulder impact",
    "11.5: Frame settle"
  ],
  "audio_events": [
    "0.0-2.0: Wet fur thrash 'flap-flap-flap' 4Hz, broadband 200-2000Hz",
    "1.2: Wave crash 'WHOOOOM' 50-200Hz fundamental",
    "2.8: Impact 'SPLAT-SQUISH' 1k-5kHz transient",
    "3.0-3.5: Suction 'pop-pop-pop-schlick' 800Hz clicks + 300Hz schlick",
    "3.5-10: Chain 'CLANK-CLANK-WHOOSH-SHRIEK' 200Hz clanks, 2kHz shrieks, Doppler whoosh",
    "4.8, 9.1: Wave booms",
    "7.0-10.5: Footfalls 'scrape-slip-thud' on wet rock",
    "0-12: Pandeireta 16th notes 180BPM, hand slaps 2&4, jingles continuous"
  ],
  "motion_constraints": [
    "Urco mass ~300kg: angular acceleration limited by paw friction (mu=0.4 wet granite). Max spin 120deg/s sustained.",
    "Chain length fixed at 4m visible. Anchor point immutable. No stretching.",
    "Percebeiro max sprint 4m/s on dry, 1.5m/s on wet algae. Leap height limited by wetsuit restriction.",
    "Octopus mass 1.5kg: ballistic trajectory calculable from launch point. No self-propulsion in air.",
    "Camera rig mass 8kg: operator momentum limits pan acceleration to 30deg/s^2.",
    "Water droplets obey gravity + wind (15m/s SW). No evaporation in 12s.",
    "Lighting changes only via cloud motion. No artificial sources."
  ]
}
